import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const F=JSON.parse('{"title":"是否引入 BFF","description":"","frontmatter":{"title":"是否引入 BFF","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/architecture/bff.md","filePath":"frontend/decisions/architecture/bff.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/architecture/bff.md"};function l(o,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="是否引入-bff" tabindex="-1">是否引入 BFF <a class="header-anchor" href="#是否引入-bff" aria-label="Permalink to &quot;是否引入 BFF&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Backend for Frontend（BFF）是面向特定客户端体验的服务端边界，负责组合下游数据、适配协议、保护凭证或支撑服务端渲染。它不应成为复制所有后端业务规则的“万能中间层”。实现基础参见<a href="/frontend/guide/engineering/server/http-bff">Node.js HTTP 服务与 BFF</a>和<a href="/frontend/guide/engineering/server/auth-validation-security">BFF 鉴权与安全边界</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>浏览器直接调用领域服务最短，但可能面对多个往返、内部协议泄露、跨域凭证和不同客户端需求。引入 BFF 可以把客户端相关编排放到服务端，同时新增一个需要部署、监控、扩容和负责的生产服务。</p><p>决策问题应是“哪些客户端约束无法由现有 API 网关或领域服务合理满足”，而不是“前端是否想拥有后端代码”。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-安全和数据边界" tabindex="-1">2.1 安全和数据边界 <a class="header-anchor" href="#_2-1-安全和数据边界" aria-label="Permalink to &quot;2.1 安全和数据边界&quot;">​</a></h3><ul><li>浏览器不得持有下游服务密钥或越过授权边界；</li><li>BFF 必须验证输入和用户权限，不能信任前端传来的角色；</li><li>敏感字段应在离开服务端前最小化；</li><li>超时、重试和缓存不能破坏下游写操作的幂等与一致性；</li><li>服务必须有明确值班、容量和故障恢复责任。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较端到端延迟、请求数量、客户端差异、协议适配、SSR 需求、安全收益、服务端团队协作、可用性依赖和长期所有权。减少前端代码行数不是独立收益，复杂度只是被转移到另一个运行环境。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-浏览器直接调用领域-api" tabindex="-1">3.1 浏览器直接调用领域 API <a class="header-anchor" href="#_3-1-浏览器直接调用领域-api" aria-label="Permalink to &quot;3.1 浏览器直接调用领域 API&quot;">​</a></h3><p>适合 API 已面向外部客户端、调用数量可控、鉴权和 CORS 边界明确的场景。链路最短，部署单元少；客户端可能承担聚合、容错和多个协议差异。</p><h3 id="_3-2-共享-api-网关或聚合层" tabindex="-1">3.2 共享 API 网关或聚合层 <a class="header-anchor" href="#_3-2-共享-api-网关或聚合层" aria-label="Permalink to &quot;3.2 共享 API 网关或聚合层&quot;">​</a></h3><p>由平台统一处理路由、认证、限流和少量通用聚合。适合多个客户端需求相近的场景，但不应持续加入某一个页面独有的展示编排。</p><h3 id="_3-3-客户端专属-bff" tabindex="-1">3.3 客户端专属 BFF <a class="header-anchor" href="#_3-3-客户端专属-bff" aria-label="Permalink to &quot;3.3 客户端专属 BFF&quot;">​</a></h3><p>由 Web 产品团队拥有面向页面的契约，聚合下游服务并隐藏内部变化。适合 Web 与移动端需求明显不同、SSR、流式响应或凭证代理等场景。代价是额外跳转和服务治理。</p><h3 id="_3-4-领域服务提供专用查询" tabindex="-1">3.4 领域服务提供专用查询 <a class="header-anchor" href="#_3-4-领域服务提供专用查询" aria-label="Permalink to &quot;3.4 领域服务提供专用查询&quot;">​</a></h3><p>当需求属于稳定业务语义，而非页面拼装时，应由领域服务提供聚合接口。把订单可用额度等规则复制进 BFF 会形成两个事实来源。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>直连领域 API</th><th>共享网关</th><th>Web BFF</th><th>领域专用查询</th></tr></thead><tbody><tr><td>页面定制</td><td>低</td><td>中</td><td>高</td><td>中</td></tr><tr><td>服务数量</td><td>最少</td><td>已有平台时较少</td><td>新增服务</td><td>不新增边界但需后端修改</td></tr><tr><td>凭证保护</td><td>取决于 API</td><td>强</td><td>强</td><td>取决于入口</td></tr><tr><td>聚合延迟</td><td>浏览器多往返</td><td>服务端并行</td><td>服务端并行</td><td>服务内部完成</td></tr><tr><td>业务规则归属</td><td>清楚</td><td>易混入网关</td><td>必须严格限制</td><td>最清楚</td></tr><tr><td>前端团队自主性</td><td>低至中</td><td>中</td><td>高</td><td>依赖领域团队</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例：客户门户的首页需要订单、账单、会员和通知四个服务；浏览器当前发出 11 个请求，移动端只需要其中一部分；公司使用 HttpOnly Session，SSR 需要在服务端读取登录态。领域团队不希望维护页面布局专属接口。</p><p>推荐引入 Web BFF，职责限定为：会话换取下游身份、并行读取四个服务、裁剪字段、转换为页面稳定契约、统一超时和追踪。账单状态计算、会员等级和订单权限仍由领域服务负责。</p><p>BFF 首期不持有业务数据库，也不为移动端复用。移动端若有不同聚合需求，应使用自己的 BFF 或由共享网关提供真正通用的能力。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>收益是减少浏览器往返、隐藏内部拓扑、支持 SSR 并把敏感凭证留在服务端。代价是增加一次网络跳转、一个可用性依赖和 Node.js 服务能力要求。</p><p>团队需要为 BFF 建立契约测试、下游超时预算、并发上限、缓存规则、追踪和降级。页面不应在 BFF 故障时完全空白，可为非关键通知设置独立降级。</p><p>退出时可以让网关或领域服务接管稳定查询契约；如果页面直接依赖大量 BFF 私有语义，迁移成本会显著上升。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>只有一个稳定公开 API 且没有 SSR 或凭证代理需求时，BFF 多半是额外跳转。</li><li>不要把跨客户端都成立的业务规则放进 BFF。</li><li>没有服务端值班、监控和安全能力的前端团队，不应低估生产责任。</li><li>仅为绕过开发环境 CORS 而建设 BFF，应先修正网关和环境配置。</li><li>BFF 不能替代 API 网关的全局限流、WAF 和组织级身份策略。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>客户门户如何获得首页聚合数据并支持 SSR</td></tr><tr><td>硬约束</td><td>HttpOnly Session；敏感字段最小化；关键账单不可错误降级；P75 小于 800ms</td></tr><tr><td>候选</td><td>浏览器直连、共享网关聚合、Web BFF、领域专用查询</td></tr><tr><td>决定</td><td>建设 Web BFF，仅负责客户端适配和编排</td></tr><tr><td>明确排除</td><td>不建业务数据库，不复制账单和权限规则，不服务移动端</td></tr><tr><td>验证指标</td><td>首页请求数、P75、下游超时率、BFF 错误预算、契约变更次数</td></tr><tr><td>接受代价</td><td>新增服务部署和值班；增加一次服务端跳转</td></tr><tr><td>退出路径</td><td>对外 DTO 独立于下游 SDK，保留网关接管可能</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>当下游服务收敛为一个稳定 API、SSR 被取消、BFF 业务规则占比持续增加、额外跳转使延迟预算无法达标，或团队无法承担值班责任时复查。若多个客户端开始复制相同聚合，应评估将其上移为领域查询或共享平台能力。</p>',36)])])}const p=a(i,[["render",l]]);export{F as __pageData,p as default};
